def is_graph_pointer_rule_char(pointer: "GraphPointer") -> bool:
    return is_rule_char(pointer.rule)


def is_graph_pointer_rule_char_exclude(pointer: "GraphPointer") -> bool:
    return is_rule_char_excluded(pointer.rule)


# The JavaScript implementation exposes `isRange` as a camelCase named export;
# keep an alias so ported call sites can use either spelling.
isRange = is_range


def _unused(*args: Optional[Any]) -> None:  # pragma: no cover - placeholder
    return None

