from typing import Any

from .types import (
    InternalRuleDefAlt,
    InternalRuleDefChar,
    InternalRuleDefCharAlt,
    InternalRuleDefCharNot,
    InternalRuleDefCharRngUpper,
    InternalRuleDefEnd,
    InternalRuleDefReference,
    InternalRuleType,
)


def is_rule_def_type(type_: Any = None) -> bool:
    if isinstance(type_, InternalRuleType):
        return True
