// Copies the reference TypeScript sources and marks type-only import specifiers
// with the `type` keyword so node's --experimental-transform-types (which has no
// type information) can elide them. No runtime code is altered.
import { cpSync, readFileSync, writeFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';

const SRC = '/workspace/reference_implementation/src';
const DST = '/tmp/diff/ref-src';

cpSync(SRC, DST, { recursive: true });

const walk = (dir) => readdirSync(dir).flatMap((entry) => {
  const full = join(dir, entry);
  return statSync(full).isDirectory() ? walk(full) : [full];
});

const files = walk(DST).filter((f) => f.endsWith('.ts') && !f.endsWith('.test.ts'));

const runtimeExports = (file) => {
  if (!existsSync(file)) return null;
  const src = readFileSync(file, 'utf-8');
  const names = new Set();
  for (const m of src.matchAll(/export\s+(?:declare\s+)?(?:abstract\s+)?(?:class|const|let|var|function|enum)\s+(\w+)/g)) {
    names.add(m[1]);
  }
  for (const m of src.matchAll(/export\s*\{([^}]*)\}/g)) {
    for (const part of m[1].split(',')) {
      const cleaned = part.trim();
      if (!cleaned || cleaned.startsWith('type ')) continue;
      const name = cleaned.split(/\s+as\s+/)[0].trim();
      if (name) names.add(name);
    }
  }
  return names;
};

for (const file of files) {
  let src = readFileSync(file, 'utf-8');
  src = src.replace(
    /import\s*\{([\s\S]*?)\}\s*from\s*['"]([^'"]+)['"]/g,
    (whole, specifiers, from) => {
      if (!from.startsWith('.')) return whole;
      const target = resolve(dirname(file), from.replace(/\.js$/, '.ts'));
      const exported = runtimeExports(target);
      if (exported === null) return whole;
      const patched = specifiers
        .split(',')
        .map((raw) => {
          const trimmed = raw.trim();
          if (!trimmed) return raw;
          if (trimmed.startsWith('type ')) return raw;
          const name = trimmed.split(/\s+as\s+/)[0].trim();
          if (exported.has(name)) return raw;
          return raw.replace(name, `type ${name}`);
        })
        .join(',');
      return `import {${patched}} from '${from}'`;
    },
  );
  writeFileSync(file, src);
}

console.log(`patched ${files.length} files`);

