import { readFileSync, writeFileSync } from 'node:fs';
import GBNF from '/tmp/diff/ref-src/index.ts';

const cases = JSON.parse(readFileSync('/tmp/diff/corpus.json', 'utf-8'));

const describeError = (err) => ({
  error: err?.name ?? 'Error',
  message: err?.message ?? String(err),
});

const rulesOf = (state) => [...state].map((rule) => (
  rule.type === 'end' ? { type: rule.type } : { type: rule.type, value: rule.value }
));

const results = cases.map(({ grammar, inputs }) => {
  const trace = { grammar, construct: null, adds: [] };
  let state;
  try {
    state = GBNF(grammar);
    trace.construct = { rules: rulesOf(state) };
  } catch (err) {
    trace.construct = describeError(err);
    return trace;
  }

  for (const input of inputs) {
    // each input is applied to the freshly constructed state, then char by char
    let entry = { input, whole: null, incremental: null };
    try {
      entry.whole = { rules: rulesOf(state.add(input)) };
    } catch (err) {
      entry.whole = describeError(err);
    }
    try {
      let cursor = GBNF(grammar);
      for (const char of [...input]) {
        cursor = cursor.add(char);
      }
      entry.incremental = { rules: rulesOf(cursor) };
    } catch (err) {
      entry.incremental = describeError(err);
    }
    trace.adds.push(entry);
  }
  return trace;
});

writeFileSync('/tmp/diff/out-js.json', JSON.stringify(results, null, 1));
console.log(`wrote ${results.length} traces`);

